81	    option (google.api.http) = {
82	      patch: "/api/v1/{setting.name=users/*/settings/*}"
83	      body: "setting"
84	    };
85	    option (google.api.method_signature) = "setting,update_mask";
86	  }
87	
88	  // ListUserSettings returns a list of user settings.
